import { expect, test } from "../../fixtures";

test.describe("sign in: session required", () => {
  test("requests without a session are rejected with not_authenticated", { tag: "@AUTH-05" }, async ({ request }) => {
    // Act: request the profile with no Authorization header and no session cookie
    const response = await request.get("/api/me");

    // Assert
    expect(response.status()).toBe(401);
    const body = await response.json();
    expect(body.error.code).toBe("not_authenticated");
  });
});
